sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float mode;
uniform float cutoff;
uniform float softness;
uniform float gamma;
uniform float choke;
uniform float showMatte;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float l = pow(saturate(luma(s)), 1.0 / max(gamma, 0.05));
    float k = smoothstep(cutoff - softness, cutoff + softness + 0.0001, l);
    float keep = mode < 0.5 ? k : 1.0 - k;
    keep = smoothstep(-choke * 0.5, 1.0 - choke * 0.5, keep);
    float4 r = c * keep;
    if (showMatte > 0.5) r = float4(float3(keep) * c.a, c.a);
    return fin(c, r, opacity);
}
